{
  "owner_file": "src/billing/receipt.js",
  "owner_symbol": "makeReceiptKey",
  "outbound_file": "src/transport/invoices.js",
  "outbound_symbol": "sendInvoice",
  "call_chain": [
    "src/app.js:checkout",
    "src/billing/submit.js:submitInvoice",
    "src/billing/receipt.js:makeReceiptKey",
    "src/transport/invoices.js:sendInvoice"
  ],
  "example_key": "invoice/acme/0007"
}
EOF
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { checkout } from './src/app.js';
import { makeReceiptKey as billingReceiptKey } from './src/billing/receipt.js';
import { makeReceiptKey as reportReceiptKey } from './src/reports/receipt.js';
import { makeReceiptKey as transportReceiptKey } from './src/transport/receipt.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['owner_file', 'owner_symbol', 'outbound_file', 'outbound_symbol', 'call_chain', 'example_key']);
const invoice = { accountId: 'acme', sequence: 7 };
let request;
await checkout(invoice, { post: (...args) => { request = args; } });
assert.equal(billingReceiptKey(invoice), answer.example_key);
assert.deepEqual(request, ['/invoices', invoice, { 'Idempotency-Key': answer.example_key }]);
assert.equal(reportReceiptKey({ id: 'acme' }), 'report:acme');
assert.equal(transportReceiptKey({ headers: { 'x-receipt': 'provider-receipt' } }), 'provider-receipt');
console.log('PASS: answer keys, billing key, outbound header, and distinct receipt helpers');
